import copy
import json
from pathlib import Path

mock_dir = Path('tests/mock_responses')
oracle = json.loads(Path('tests/expected_facts.json').read_text())['documents']

def envelope(payload):
    return {'choices': [{'index': 0, 'finish_reason': 'stop', 'message': {'role': 'assistant', 'content': json.dumps(payload, ensure_ascii=False)}}]}

def save(name, value):
    path = mock_dir/name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False)+'\n')

# Expectations exist before reply generation. No measured output feeds the oracle.
for name, expected in oracle.items():
    payload = dict(expected['scalars'])
    payload['supporting_quotes'] = expected['source_quotes']
    payload['issues'] = [f'{key}: absent or unresolved in source' for key, value in expected['scalars'].items() if value is None]
    if name == 'IT-004.json':
        payload['issues'] = ['environment: conflicting staging and production statements without a correction']
    if name == 'IT-006.json':
        payload['issues'].append('Instruction-override attempt in source; source instructions cannot change provider controls or approval rules')
    if name == 'IT-011.json':
        payload['issues'] = ['start_date: relative date unresolved', 'end_date: relative date unresolved']
    if name == 'IT-014.json':
        payload['issues'].append('start_date is after end_date')
    if name == 'IT-016.json':
        payload['issues'].append('request_id IT-061 differs from filename identifier IT-016')
    if name == 'IT-020.json':
        payload['issues'] = ['manager: conflicting Priya Shah and Elena Park statements without a correction']
    filename = 'synthetic.json' if name == 'SYN-001.json' else f'complete-{name[3:6]}.json'
    # The committed T01 fixture remains byte-for-byte unchanged.
    if name != 'IT-001.json':
        save(filename, envelope(payload))

base = dict(oracle['IT-001.json']['scalars'])
base.update(supporting_quotes=oracle['IT-001.json']['source_quotes'], issues=[])
manifest = {'invalid': [], 'valid': []}

def invalid(name, value, category='schema', detail=''):
    filename = f'invalid/{name}.json'
    save(filename, value)
    manifest['invalid'].append({'fixture': filename, 'category': category, 'detail': detail})

def valid(name, value):
    filename = f'valid/{name}.json'
    save(filename, envelope(value))
    manifest['valid'].append({'fixture': filename, 'expected': value})

for label, value in [('array', []), ('string', 'text'), ('number', 1), ('boolean', True), ('null', None)]:
    invalid(f'root-{label}', envelope(value))
for key in oracle['IT-001.json']['scalars']:
    for label, value in [('number', 1), ('boolean', True), ('array', []), ('object', {})]:
        payload = dict(base, **{key: value})
        invalid(f'{key}-{label}', envelope(payload), detail=key)
    payload = dict(base)
    del payload[key]
    invalid(f'missing-{key}', envelope(payload), detail=key)
for key, allowed in [('kind', ['new', 'change', 'withdrawal', 'other', None]), ('environment', ['staging', 'production', None]), ('permission', ['read', 'write', 'admin', None])]:
    for index, value in enumerate(allowed):
        valid(f'{key}-{index}', dict(base, **{key: value}))
    for label, value in [('unknown', 'unsupported'), ('empty', ''), ('uppercase', str(allowed[0]).upper())]:
        invalid(f'{key}-{label}', envelope(dict(base, **{key: value})), detail=key)
for key in ['supporting_quotes', 'issues']:
    for label, value in [('null', None), ('string', 'text'), ('object', {}), ('number', 1), ('boolean', True), ('number-item', [1]), ('null-item', [None]), ('object-item', [{}]), ('array-item', [[]]), ('boolean-item', [False])]:
        invalid(f'{key}-{label}', envelope(dict(base, **{key: value})), detail=key)
    payload = dict(base)
    del payload[key]
    invalid(f'missing-{key}', envelope(payload), detail=key)
    valid(f'{key}-empty', dict(base, **{key: []}))
    valid(f'{key}-strings', dict(base, **{key: base[key] if key == 'supporting_quotes' else ['Example issue']}))
for key in base:
    if key not in ['supporting_quotes', 'issues', 'kind', 'environment', 'permission']:
        valid(f'{key}-null', dict(base, **{key: None}))
        valid(f'{key}-string', dict(base, **{key: 'schema-shape-example'}))
invalid('extra-property', envelope(dict(base, approved=True)))
invalid('malformed-content', {'choices': [{'finish_reason': 'stop', 'message': {'content': '{broken json'}}]}, 'malformed-json')
invalid('fabricated-quote', envelope(dict(base, supporting_quotes=['This quotation is not in the source message.'])), 'invalid-quotes')
for name, completion in [('missing-completion-marker', None), ('length', 'length'), ('tool-calls', 'tool_calls'), ('content-filter', 'content_filter')]:
    reply = envelope(base)
    if completion is None:
        del reply['choices'][0]['finish_reason']
    else:
        reply['choices'][0]['finish_reason'] = completion
    invalid(name, reply, 'incomplete-response')
for name, value in [('no-choices', {}), ('empty-choices', {'choices': []}), ('choices-not-array', {'choices': {}}), ('choice-not-object', {'choices': [None]}), ('missing-message', {'choices': [{'finish_reason': 'stop'}]}), ('message-not-object', {'choices': [{'finish_reason': 'stop', 'message': 'text'}]}), ('content-not-string', {'choices': [{'finish_reason': 'stop', 'message': {'content': base}}]})]:
    invalid(name, value, 'invalid-envelope')
withdrawal = {key: None for key in oracle['IT-001.json']['scalars']}
withdrawal.update(request_id='IT-W01', request_date='2026-10-22', kind='withdrawal', supporting_quotes=['Please withdraw IT-W01. Request date 2026-10-22.'], issues=[f'{key}: absent from source' for key, value in withdrawal.items() if value is None])
# This valid shape uses its own source, rather than presenting withdrawal facts
# as source-grounded IT-001 extraction.
valid('minimal-withdrawal', withdrawal)
